class Person:
    def __init__(self, name, alter):
        self.name = name
        self.alter = alter

    def ___(self):
        return f"{self.name} ({self.alter})"

p1 = Person("John", 36)
print(p1)

class Konto:
    def __init__(self):
        self.stand = 0

    def einzahlen(self, betrag):
        self.stand += betrag
        return self.stand

k = Konto()
k.einzahlen(50)
print(k.einzahlen(20))

class Rechteck:
    def __init__(self, b, h):
        self.b = b
        self.h = h

    def flaeche(self):
        return self.b * self.h

    def __str__(self):
        return f"Rechteck {self.b}x{self.h}"

r = Rechteck(3, 4)
print(r, r.flaeche())

class Lampe:
    def __init__(self):
        self.an = False

    def schalten(self):
        self.an = not self.an

l = Lampe()
l.schalten()
l.schalten()
l.schalten()
print(l.an)
